//! Opt-in standalone Checker request over the EXISTING resident compiler.
use super::{protocol,transport,selected_report_wire as wire};use crate::request::BuildRequest;use serde::{Deserialize,Serialize};use std::{error::Error,io,path::PathBuf};
#[derive(Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub(super)struct Request{pub(super)build:BuildRequest,pub(super)display:PathBuf,#[serde(default)]pub(super)caller_directory:Option<PathBuf>,pub(super)configuration:Option<PathBuf>,#[serde(default)]pub(super)json:bool}
impl Request{pub(super)fn qualify(&self)->io::Result<()>{crate::native_checker::require_prepared_shape_with_caller(&self.build,&self.display,self.caller_directory.as_deref(),self.configuration.as_deref())?;super::build_admission::validate(&self.build).map_err(io::Error::other)?;let root=self.build.project.parent().ok_or_else(||io::Error::new(io::ErrorKind::InvalidInput,"Checker project parent unavailable"))?;let cache=self.build.cache_root.as_deref().ok_or_else(||io::Error::new(io::ErrorKind::InvalidInput,"Checker cache unavailable"))?;super::generation::validate_cache_outside(root,cache)}}
fn invocation(arguments:&[String])->Result<Option<Request>,Box<dyn Error>>{
 let selected=match dq_analyze::native_cli_client::checker_caller_paths::select(arguments,false)?{dq_analyze::native_cli_client::checker_caller_paths::Selection::Check(actual)=>actual,dq_analyze::native_cli_client::checker_caller_paths::Selection::Unknown(arg)=>{eprintln!("unknown argument: {arg}");return Ok(None)}};
 let resolved=dq_analyze::native_cli_client::checker_caller_paths::resolve_selected_using(selected,std::env::current_dir)?;
 let cache=std::fs::canonicalize(crate::request::client_cache_root()?)?;
 let native=crate::native_checker::Request{project:resolved.project,configuration:resolved.configuration,cache_root:cache,workers:2,timeout_seconds:300};let build=native.build()?;
 let caller_directory=resolved.caller_directory;let request=Request{build,display:resolved.display,caller_directory,configuration:native.configuration,json:resolved.json};request.qualify()?;Ok(Some(request))
}
pub fn run_cli(arguments:&[String])->Result<u8,Box<dyn Error>>{let Some(request)=invocation(arguments)?else{return Ok(0)};let project=request.build.project.clone();let json=request.json;let cache=request.build.cache_root.clone().ok_or_else(||io::Error::other("Checker cache absent"))?;let mut stream=super::connect_generation()?;transport::set_timeout(&mut stream,transport::BUILD_DEADLINE)?;protocol::send(&mut stream,&protocol::Request::CheckerText(request))?;wire::receive_checker_text(&mut stream,&cache,&project,json)?.publish(&mut io::stdout().lock()).map_err(Into::into)}
#[cfg(test)]mod tests{use super::*;#[test]fn resident_checker_request_denies_compile_workspace_and_caller_fields(){let(_,build,_,_)=crate::generation_test_fixture::fixture();let request=Request{display:build.project.clone(),caller_directory:None,configuration:None,json:false,build};assert!(request.qualify().is_err());let mut data=serde_json::to_value(&request).unwrap();data["caller_complete"]=serde_json::json!(true);assert!(serde_json::from_value::<Request>(data).is_err());for flag in["--json","--parse-only","--version"]{assert!(crate::native_checker::Request::from_arguments(&[flag.into()],PathBuf::from(if cfg!(windows){"E:/dq-cache/checker"}else{"/cache/checker"})).is_err());}}}

#[cfg(test)]mod project_cache_admission_controls{use super::*;
 fn actual(label:&str)->(Request,PathBuf){let root=std::fs::canonicalize(crate::test_scratch::dir(label)).unwrap();let cache=std::fs::canonicalize(crate::test_scratch::dir(&format!("{label}-cache"))).unwrap();let project=root.join("project.dme");std::fs::write(&project,"/proc/p()\n    return 1\n").unwrap();let native=crate::native_checker::Request{project:project.clone(),configuration:None,cache_root:cache,workers:1,timeout_seconds:60};let build=native.build().unwrap();(Request{build,display:project,caller_directory:None,configuration:None,json:false},root)}
 #[test]fn actual_checker_project_cache_needs_no_fabricated_workspace(){let(request,_)=actual("checker-real-project-cache");assert!(request.build.policy_inputs.as_ref().unwrap().workspace.is_none());request.qualify().unwrap();assert!(super::super::generation::validate_cache(&request.build).unwrap_err().to_string().contains("generation workspace unavailable"),"workspace generation guard is unchanged");}
 #[test]fn actual_checker_project_cache_refuses_source_overlap_file_and_preserves_absent_io(){let(mut request,root)=actual("checker-real-project-cache-refuse");let inside=root.join("cache");std::fs::create_dir(&inside).unwrap();request.build.cache_root=Some(inside);assert_eq!(request.qualify().unwrap_err().kind(),io::ErrorKind::InvalidInput);let outside=crate::test_scratch::dir("checker-cache-file");let file=outside.join("cache-file");std::fs::write(&file,b"not a cache directory").unwrap();request.build.cache_root=Some(file);assert_eq!(request.qualify().unwrap_err().kind(),io::ErrorKind::InvalidInput);request.build.cache_root=Some(outside.join("absent-cache"));let actual=request.qualify().unwrap_err();assert_eq!(actual.kind(),io::ErrorKind::NotFound);assert!(actual.raw_os_error().is_some());}
}
